def linear_search(arr, target):
    for i in range(len(arr)):
        if arr[i] == target:
            return i

    return -1

print(linear_search([3, 8, 5, 11, 2], 11))
print(linear_search([3, 8, 5, 11, 2], 10))

def count_occurrences(arr, target):
    count = 0

    for value in arr:
        if value == target:
            count += 1

    return count

print(count_occurrences([1, 2, 2, 3], 2))

def last_occurrence(arr, target):
    for i in range(len(arr) - 1, -1, -1):
        if arr[i] == target:
            return i
    return -1

print(last_occurrence([1, 2, 2, 3, 2, 4], 2))

def search_in_range(arr, target, start, end):
    start = max(0, start)
    end = min(len(arr) - 1, end)
    for i in range(start, end + 1):
        if arr[i] == target:
            return i
    return -1
